<template><div class="page-card"><h2>分类管理</h2><el-button type="primary" @click="save">新增分类</el-button><el-table :data="rows" style="margin-top:16px"><el-table-column prop="name" label="分类名称"/><el-table-column prop="description" label="描述"/><el-table-column label="操作"><template #default="s"><el-button link @click="save(s.row)">编辑</el-button></template></el-table-column></el-table></div></template>
<script setup>import {ref,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import http from '../api/http';const rows=ref([]);async function load(){const r=await http.get('/categories');rows.value=r.data}async function save(row){const name=prompt('分类名称',row?.name||'');if(!name)return;const data={id:row?.id,name,description:row?.description||''};const r=row?await http.put('/categories',data):await http.post('/categories',data);if(r.code===200){ElMessage.success('保存成功');load()}}onMounted(load)</script>
